\label{ass:one-sided-margin}
There are constants $C_m>0$, $beta>0$, and $t_0>0$ such that
\begin{equation}
\label{eq:one-sided-margin}
\mathbb P\{0<M_q(w^\star)\le t\}
\le C_m t^beta,
\qquad 0<t\le t_0.
\end{equation}

\label{thm:buffered-main}
Assume \cref{ass:one-sided-margin}, let $\varepsilon_N$ be given by \eqref{eq:epsilon-N}, and suppose $2\varepsilon_N\le t_0$.  Let $\widehat w_{\varepsilon_N}$ be any minimizer in \eqref{eq:buffered-erm}.  Then, with probability at least $1-\delta$ over both sources of randomness,
\begin{equation}
\label{eq:buffered-bound-exact}
R(\widehat w_{\varepsilon_N})-R(w^\star)
\le
2\mathfrak v_Q(\delta)
+C_m(2\varepsilon_N)^beta.
\end{equation}
Substituting \eqref{eq:epsilon-N} and \eqref{eq:vq} gives the explicit rate stated in \eqref{eq:intro-main}.

\label{lem:side}
Define
\begin{equation}
\label{eq:theta}
theta(G)
:=
\int_{-1}^1\operatorname{sgn}(z)\,\,\mathrm d G(z)
=
G((0,1])-G([-1,0)).
\end{equation}
Every $t>1/2$ has risk $G([-1,0])$, every $t<1/2$ has risk $G([0,1])$, and $t=1/2$ has risk one.  Hence the optimal side is the sign of $theta(G)$ when $theta(G)\ne0$; when $theta(G)=0$, the two sides have equal risk.  Choosing the wrong side incurs excess risk $|theta(G)|$.

\label{lem:moment-equivalence}
For probability measures $G,H$ on $[-1,1]$, the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item $K_nG=K_nH$;
\item $\int P\,\,\mathrm d G=\int P\,\,\mathrm d H$ for every algebraic polynomial $P$ of degree at most $n$;
\item $\int z^j\,\,\mathrm d G(z)=\int z^j\,\,\mathrm d H(z)$ for $j=0,\dots,n$.
\end{enumerate}

\label{thm:scalar-modulus}
There are universal constants $0<c<C<infinity$ such that, for every $Q,n\ge1$,
\begin{equation}
\label{eq:scalar-modulus-chain}
c\,omega_{n,beta,L}(Q^{-1/2})
\le
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\le
\mathcal R^{\mathrm{abs}}_{Q,n}(beta,L)
\le
C\,omega_{n,beta,L}(Q^{-1/2}).
\end{equation}

\label{thm:identification-floor}
For every fixed $beta>0$ and $L\ge1$, there are constants $0<c_{beta,L}<C_{beta,L}<infinity$ such that
\begin{equation}
\label{eq:identification-floor}
 c_{beta,L}n^{-beta}
\le
omega_{n,beta,L}(0)
\le
C_{beta,L}n^{-beta}
\qquad\text{for every }n\ge1.
\end{equation}
Consequently,
\begin{equation}
\label{eq:N-only-lower}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\ge c_{beta,L}n^{-beta}
\qquad\text{for every }Q.
\end{equation}
Since $n=2N$, the finite-generation identification floor is $\Theta(N^{-beta})$.

\label{thm:rootQ-scalar}
For every $n\ge1$, $beta>0$, $L\ge1$, and $0<\varepsilon\le1$,
\begin{equation}
\label{eq:rootQ-modulus}
omega_{n,beta,L}(\varepsilon)\ge\varepsilon.
\end{equation}
Consequently, for every $Q,n\ge1$,
\begin{equation}
\label{eq:rootQ-scalar}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\ge cQ^{-1/2}
\end{equation}
for a universal constant $c>0$.  Both claims hold on a two-atom subclass supported on $Z\in\{-1,+1\}$ and therefore under a hard margin.

\label{thm:observed-transfer}
There are universal constants $c_0,c_1>0$ such that, for every $Q,n\ge1$, $beta>0$, and $L\ge1$,
\begin{equation}
\label{eq:observed-transfer}
 c_1\,omega_{n,beta,L}(c_0Q^{-1/2})
\le
\mathcal R^{\mathrm{obs}}_{Q,n}(beta,L)
\le
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L).
\end{equation}
One may take $c_0=1/64$ and $c_1=1/16$.

\label{cor:observed-modulus}
For fixed $beta,L$ and every $Q,n\ge1$,
\begin{equation}
\label{eq:observed-modulus-equivalence}
\mathcal R^{\mathrm{obs}}_{Q,n}(beta,L)
\asymp
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\asymp
omega_{n,beta,L}(Q^{-1/2}),
\end{equation}
where the implicit constants are universal.

\label{cor:general-lower-transfer}
Fix $K\ge2$ and $A\ge2$.  For each $Z\in\mathfrak Z_{beta,L}$,
consider the binary-answer $K$-model environment on $([0,1],\lambda)$ in
which models 1 and 2 obey \eqref{eq:antisymmetric}, while every model
$i\ge3$ returns either answer with probability $1/2$.  Then
\begin{equation}
\label{eq:general-lower-transfer}
\inf_{\widehat w}
\sup_{Z\in\mathfrak Z_{beta,L}}
\mathbb E_Z\!
\left[
R_Z(\widehat w)-\inf_{w\inDelta_K}R_Z(w)
\right]
\ge
\mathcal R^{\mathrm{obs}}_{Q,2N}(beta,L)
\gtrsim
omega_{2N,beta,L}(Q^{-1/2}).
\end{equation}

\label{rem:nonatomic}
The nonatomic formulation keeps the two sample sizes conceptually separate: $Q$ counts fresh questions, while $N$ is the generation budget attached to each question.
If questions are instead represented literally as finite strings, let $\mathcal X=\Sigma^\star$ with the discrete sigma-field $2^{\Sigma^\star}$.  The same constant-factor transfer rate holds for the distribution-free class
\[
\mathfrak P^{\mathrm{obs}}_{beta,L}
:=
\left\{
(\mathcal Q,Z):
\mathcal Q\in\mathcal P(\mathcal X),\;
Z:\mathcal X\to[-1,1],\;
Z_\#\mathcal Q\in\mathcal G_{beta,L}
\right\}.
\]
Indeed, we can use the same construction, taking $\mathcal Q$ to be uniform
on $M$ distinct strings, randomly assigning the atoms of each equal-weight
approximation to those strings, and then choosing $M\gg Q^2$.  The proof otherwise repeats the
discretization, permutation coupling, and collision argument above and is omitted.

\label{thm:plugin-scalar}
For a constant $C=C(beta,L)$,
\begin{equation}
\label{eq:plugin-scalar}
\sup_{G\in\mathcal G_{beta,L}}
\mathbb E_G|\widehattheta_{\mathrm{plug}}-theta(G)|
\le
C\left(Q^{-1/2}+n^{-beta/2}\right).
\end{equation}
The same expression upper-bounds the decision regret.

\label{cor:question-limited}
If $Q\le c_0 n^beta$ for a fixed constant $c_0$, then
\begin{equation}
\label{eq:question-limited}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\asymp_{beta,L,c_0}
Q^{-1/2}.
\end{equation}

\label{lem:bernstein-identity}
The map $a\mapsto P_a$ is a linear bijection from $\mathbb R^{n+1}$ onto $\Pi_n$.  Equivalently, every $P\in\Pi_n$ has unique coefficients $a_0(P),\dots,a_n(P)$ such that
\begin{equation}
\label{eq:bernstein-representation}
P(z)
=
\sum_{k=0}^n a_k(P)\,
 b_{k,n}\!\left(\frac{1+z}{2}\right).
\end{equation}

\label{prop:bias-stability}
For every $P\in\Pi_n$ and $G\in\mathcal G_{beta,L}$,
\begin{equation}
\label{eq:bias-stability}
\mathbb E_G|\widehattheta_P-theta(G)|
\le
\int|P(z)-\operatorname{sgn}(z)|\,\,\mathrm d G(z)
+
\frac{A(P)}{2\sqrt Q}.
\end{equation}

\label{prop:durrmeyer}
For $0\le j\le n$,
\begin{equation}
\label{eq:durrmeyer-eigen}
D_nL_j=\lambda_{j,n}L_j,
\qquad
\lambda_{j,n}
=
\frac{n!(n+1)!}{(n-j)!(n+j+1)!}
=
\prod_{r=0}^{j-1}\frac{n-r}{n+r+2}.
\end{equation}
Define $v_j:=\lambda_{j,n}^{-1/2}T_n^*L_j$.  Then $v_0,\dots,v_n$ form an orthonormal basis of $\mathsf H_n$, and
\begin{equation}
\label{eq:durrmeyer-svd}
T_na
=
\sum_{j=0}^n
\sqrt{\lambda_{j,n}}\,
\left\langlea,v_j\right\rangle_{\nu_n}L_j.
\end{equation}

\label{prop:coefficient-spectral}
Let $P\in\Pi_d$, $d\le n$, and write its shifted-Legendre expansion as
$\widetilde P=\sum_{j=0}^d c_jL_j$.
Then its degree-$n$ Bernstein coefficient vector satisfies
\begin{equation}
\label{eq:coefficient-spectral}
\frac1{n+1}\sum_{k=0}^n a_k(P)^2
=
\sum_{j=0}^d\frac{c_j^2}{\lambda_{j,n}}.
\end{equation}
In particular, since $\kappa_{d,n}:=\lambda_{d,n}^{-1/2}$, one has
\begin{equation}
\label{eq:range-spectral}
A(P)
\le
2\sqrt{n+1}\,\kappa_{d,n}\norm{\widetilde P}_{L_2[0,1]}.
\end{equation}

\label{thm:spectral-modulus-lower}
Fix $0<beta\le1$ and $L\ge1$.  There are constants $0<c_{beta,L}<C_{beta,L}<infinity$ such that, for every $n\ge2$ and every integer $1\le d\le n-1$,
\begin{equation}
\label{eq:spectral-modulus-lower}
omega_{n,beta,L}\!\left(
C_{beta,L}\frac{n+1}{\kappa_{d+1,n}}
\right)
\ge
c_{beta,L}d^{-beta}.
\end{equation}
If $1/2<beta\le1$, the following stronger bound holds:
\begin{equation}
\label{eq:spectral-modulus-lower-L2}
omega_{n,beta,L}\!\left(
\frac{C_{beta,L}}{\kappa_{d+1,n}}
\right)
\ge
c_{beta,L}d^{-beta}.
\end{equation}

\label{prop:explicit-spectral-rates}
Fix $beta>0$ and $L\ge1$.  There are constants $c_0,c,C>0$ and $n_0\ge2$, depending only on $(beta,L)$, such that, for every $n\ge n_0$, the following statements hold.
\begin{enumerate}[label=(\alph*)]
\item If $0<beta\le1$ and $y_{Q,n}\le c_0n$, then
\begin{equation}
\label{eq:spectral-explicit-lower}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\ge
c\,(ny_{Q,n})^{-beta/2}.
\end{equation}
If $1/2<beta\le1$, the same assertion holds with $y_Q^{(2)}$ in place of $y_{Q,n}$, both in the condition and in the bound.

\item If $1\le x_{Q,n}\le c_0n$, then
\begin{equation}
\label{eq:intermediate-upper}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\le
C\,(nx_{Q,n})^{-beta/2}.
\end{equation}
The bound is achieved by the polynomial-moment estimator with degree $d\asymp\sqrt{nx_{Q,n}}$.
\end{enumerate}

\label{thm:rigorous-middle}
Fix $0<beta\le1$, $L\ge1$, and $\eta>0$.  There are constants $0<c_{beta,L,\eta}<C_{beta,L,\eta}<infinity$, $c_\eta>0$, and $n_0$ such that, for every $n\ge n_0$ and
\begin{equation}
\label{eq:rigorous-middle-range}
n^{beta+1+\eta}
\le Q
\le e^{c_\eta n},
\end{equation}
\begin{equation}
\label{eq:rigorous-middle}
c_{beta,L,\eta}
[n\log Q]^{-beta/2}
\le
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\le
C_{beta,L,\eta}
[n\log Q]^{-beta/2}.
\end{equation}
The upper bound is attained by the pooled polynomial-moment estimator with degree $d\asymp\sqrt{n\log Q}$.

Under the lower inequality in \eqref{eq:rigorous-middle-range},
\[
x_{Q,n}
\asymp_{beta,\eta}
y_{Q,n}
\asymp_{beta,\eta}
\log Q.
\]
The upper inequality in \eqref{eq:rigorous-middle-range}, with $c_\eta$ sufficiently small, places both logarithmic scales in the ranges required by \cref{prop:explicit-spectral-rates}.  Combining its lower and upper assertions proves \eqref{eq:rigorous-middle}.

\label{conj:Psi}
For fixed $beta,L$, the scalar minimax risk satisfies
\begin{equation}
\label{eq:Psi}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\asymp_{beta,L}
\Psi_beta(Q,n),
\qquad
\Psi_beta(Q,n)
:=
\inf_{1\le d\le n}
\left\{
 d^{-beta}
+
\frac{\kappa_{d,n}}{\sqrt Q}
\right\}.
\end{equation}

\label{lem:margin-accuracy}
With probability at least $1-\delta/4$ over the generations, conditional on $q_1,\dots,q_Q$,
\begin{equation}
\label{eq:margin-accuracy}
\sup_{j\le Q}\sup_{w\inDelta_K}
\left|\widehat M_{q_j}(w)-M_{q_j}(w)\right|
\le\varepsilon_N.
\end{equation}
Consequently, on this event, for every $j$ and $w$,
\begin{equation}
\label{eq:sandwich}
\mathbf 1\{M_{q_j}(w)\le0\}
\le
\mathbf 1\{\widehat M_{q_j}(w)\le\varepsilon_N\}
\le
\mathbf 1\{M_{q_j}(w)\le2\varepsilon_N\}.
\end{equation}

\label{lem:clean-risk-deviation}
Fix two deterministic thresholds $s_1,s_2\ge0$.
With probability at least $1-\delta/4$ over the questions,
\begin{equation}
\label{eq:uniform-margin-deviation}
\sup_{w\inDelta_K,\,t\in\{s_1,s_2\}}
\left|
\frac1Q\sum_{j=1}^Q\mathbf 1\{M_{q_j}(w)\le t\}
-
\mathbb P\{M_q(w)\le t\}
\right|
\le\mathfrak v_Q(\delta).
\end{equation}

\label{lem:capacity}
Let $p=K-1$.  For every $m\ge1$ and $t\ge0$,
\begin{equation}
\label{eq:growth-bound}
\Pi_{\mathcal F_t}(m)
\le
B\bigl(m(A-1),p\bigr).
\end{equation}
Consequently,
\begin{equation}
\label{eq:buffered-growth-bound}
\Pi_{\mathcal F_{\mathrm{buf}}}(m)
\le
2B\bigl(m(A-1),p\bigr),
\qquad
\log\Pi_{\mathcal F_{\mathrm{buf}}}(m)
\le C\bigl(1+p\log(eAm)\bigr),
\end{equation}
where $C$ is universal.

\label{lem:growth-deviation}
Let $\mathcal H$ be a class of binary functions and let $P_Q$ be the
empirical measure of $Q$ independent observations from $P$.  For every
$u>0$,
\begin{equation}
\label{eq:vc-ineq}
\mathbb P\left\{
\sup_{h\in\mathcal H}|P_Qh-Ph|>u
\right\}
\le
2\Pi_{\mathcal H}(2Q)
\exp\left(-\frac{Qu^2}{2}\right).
\end{equation}

\label{lem:margin-class-properties}
The class $\mathcal G_{beta,L}$ is convex, invariant under reflection
$G\mapsto G^\dagger$, where $G^\dagger(B)=G(-B)$, and compact for weak convergence.  Every $G\in\mathcal G_{beta,L}$ satisfies $G(\{0\})=0$.  The functional $G\mapstotheta(G)$ and the channel map $G\mapsto K_nG$ are affine and continuous on $\mathcal G_{beta,L}$.  Moreover,
\begin{equation}
\label{eq:reflection-properties}
theta(G^\dagger)=-theta(G),
\qquad
(K_nG^\dagger)(k)=(K_nG)(n-k),
\quad k=0,\dots,n.
\end{equation}

\label{thm:modulus-upper}
Under $(p,\tau)\in\mathcal X$, observe $Y_1,\dots,Y_Q\overset{\mathrm{iid}}{\sim}p$.  Then
\begin{equation}
\label{eq:modulus-upper}
\inf_{\widehat\tau}
\sup_{(p,\tau)\in\mathcal X}
\mathbb E_p|\widehat\tau-\tau|
\le
\frac72\,
omega_{\mathcal X}(32Q^{-1/2}).
\end{equation}
The infimum is over all possibly randomized estimators $\widehat\tau$ based on these observations.
The projection $(p,\tau)\mapsto p$ need not be injective, so the result allows $omega_{\mathcal X}(0)>0$.

\label{lem:modulus-scaling}
For $0<\varepsilon_1\le\varepsilon_2$,
\begin{equation}
\label{eq:modulus-scaling}
omega_{\mathcal X}(\varepsilon_1)
\le
omega_{\mathcal X}(\varepsilon_2)
\le
\left(\frac{\varepsilon_2}{\varepsilon_1}\right)^2
omega_{\mathcal X}(\varepsilon_1).
\end{equation}
Consequently, replacing an argument of the modulus by any fixed positive multiple changes its value by at most a fixed multiplicative factor.

First suppose that every distribution in $\mathcal P_0\cup\mathcal P_1$ has strictly positive coordinates.  Let $(p_0,q_1)$ maximize the Hellinger affinity
\[
\rho(p,q):=\sum_{i=1}^m\sqrt{p_iq_i}
\]
over $\mathcal P_0\times\mathcal P_1$.  For fixed $q_1$, the map $p\mapsto\rho(p,q_1)$ is concave.  First-order optimality at $p_0$ along every segment from $p_0$ to $p\in\mathcal P_0$ gives
\begin{equation}
\label{eq:affinity-first-order-p}
\sum_{i=1}^m p_i\sqrt{\frac{q_{1i}}{p_{0i}}}
\le
\sum_{i=1}^m p_{0i}\sqrt{\frac{q_{1i}}{p_{0i}}}
=\rho(p_0,q_1).
\end{equation}
Similarly, for every $q\in\mathcal P_1$,
\begin{equation}
\label{eq:affinity-first-order-q}
\sum_{i=1}^m q_i\sqrt{\frac{p_{0i}}{q_{1i}}}
\le\rho(p_0,q_1).
\end{equation}
Use the likelihood-ratio test between $p_0^{\otimes k}$ and $q_1^{\otimes k}$, namely,
$\phi = \mathbf 1 \left\{\prod_{j=1}^k q_1(Y_j)/p_0(Y_j)\ge1 \right\}$.  For $p\in\mathcal P_0$, Markov's inequality and \eqref{eq:affinity-first-order-p} yield
\begin{align*}
\mathbb E_{p^{\otimes k}}\phi
\;\le\;
\mathbb E_{p^{\otimes k}}
\prod_{j=1}^k
\left(\frac{q_1(Y_j)}{p_0(Y_j)}\right)^{1/2}
=
\left[
\sum_{i=1}^m p_i\sqrt{\frac{q_{1i}}{p_{0i}}}
\right]^k
\le\rho(p_0,q_1)^k.
\end{align*}
The inverse likelihood ratio and \eqref{eq:affinity-first-order-q} give the same bound for the other error.  Since maximizing affinity is equivalent to minimizing Hellinger distance,
\[
\rho(p_0,q_1)=1-\frac12r_*^2,
\]
which proves \eqref{eq:robust-test-error} under strict positivity.

To remove that assumption, let $u$ be the uniform law and, for $\eta\in(0,1)$, set
\[
\mathcal P_j^\eta
:=
\{(1-\eta)p+\eta u:p\in\mathcal P_j\},
\qquad j=0,1.
\]
Apply the preceding construction to obtain a randomized test $\phi_\eta$, viewed as a vector in $[0,1]^{m^k}$.  Along a sequence $\eta_\ell\downarrow0$, compactness gives coordinatewise convergence to a randomized test $\phi$.  Uniform continuity of Hellinger affinity shows that the maximal affinities of the smoothed sets converge to the maximal affinity of the original sets.  For each fixed $p\in\mathcal P_0$ and $q\in\mathcal P_1$, the corresponding smoothed product laws converge in total variation to $p^{\otimes k}$ and $q^{\otimes k}$.  Together with coordinatewise convergence of the tests on the finite sample space, this implies convergence of their testing risks.  Passing to the limit proves the result on the boundary of the simplex.

\label{thm:pooled-lower}
For every fixed $beta>0$ and $L\ge1$, there are constants $c_0,c_1>0$ such that, for every $n\ge1$ and $0<\varepsilon\le c_0$,
\begin{equation}
\label{eq:pooled-modulus-lower}
omega_{n,beta,L}(\varepsilon)
\ge
c_1\left(\frac{\varepsilon^2}{n}\right)^{beta/(beta+2)}.
\end{equation}
Consequently, there is a constant $c_{beta,L}>0$ such that
\begin{equation}
\label{eq:pooled-lower}
\mathcal R^{\mathrm{dec}}_{Q,n}(beta,L)
\ge
c_{beta,L}(Qn)^{-beta/(beta+2)}
\end{equation}
for every $Q,n\ge1$.

\label{lem:permutation-embedding}
Let $G_M=M^{-1}\sum_{r=1}^M\delta_{z_r}$ be an equal-weight measure.  Partition $[0,1]$ into $M$ intervals $I_1,\dots,I_M$ of equal length.  Draw a uniform random permutation $\Pi$ of $[M]$ and define the deterministic map
\[
Z_\Pi(q)=z_{\Pi(r)},
\qquad q\in I_r.
\]
Let $\overline{\mathbb P}^{Q,n}_{G_M,M}$ be the law of the full sample in \eqref{eq:full-observed-scalar} after averaging over $\Pi$.  Then
\begin{equation}
\label{eq:permutation-TV}
\operatorname{TV}\!\left(
\overline{\mathbb P}^{Q,n}_{G_M,M},
\lambda^{\otimes Q}\otimes(K_nG_M)^{\otimes Q}
\right)
\le
3\alpha_{Q,M},
\qquad
\alpha_{Q,M}
:=
1-\frac{(M)_Q}{M^Q}
\le
\frac{Q(Q-1)}{2M},
\end{equation}
where $(M)_Q=M(M-1)\cdots(M-Q+1)$, with $(M)_Q=0$ when $Q>M$.

\label{lem:jackson}
For every $s>0$, there is $C_s$ such that, for every integer $n\ge1$, there is $P_n\in\Pi_n$ satisfying
\begin{equation}
\label{eq:jackson-bound}
\norm{P_n}_{L_infinity[-1,1]}\le1,
\qquad
|P_n(x)-\operatorname{sgn}(x)|
\le
C_s\min\{1,(n|x|)^{-s}\}
\end{equation}
for every $x\in[-1,1]\setminus\{0\}$.

\label{lem:integrated-approx}
If $G\in\mathcal G_{beta,L}$ and $s>beta$ in \cref{lem:jackson}, then, for every $n\ge1$,
\begin{equation}
\label{eq:integrated-approx}
\int|P_n(z)-\operatorname{sgn}(z)|\,\,\mathrm d G(z)
\le C_{beta,L,s}n^{-beta}.
\end{equation}

\label{lem:weighted-sign}
There are $0<c_beta<C_beta<infinity$ such that
\begin{equation}
\label{eq:weighted-sign-rate}
c_beta n^{-beta}
\le
E_n(beta)
:=
\inf_{P\in\Pi_n}
\int|\operatorname{sgn}(x)-P(x)|\,\,\mathrm d\mu_beta(x)
\le
C_beta n^{-beta}.
\end{equation}

\label{lem:duality-moment-pair}
For every integer $m\ge1$, there is an odd function $h_m\in L_infinity(\mu_beta)$ satisfying
\begin{equation}
\label{eq:hm-properties}
\norm{h_m}_infinity\le1,
\qquad
\int P(z)h_m(z)\,\,\mathrm d\mu_beta(z)=0
\quad\text{for every }P\in\Pi_m,
\end{equation}
and
\begin{equation}
\label{eq:hm-target}
\int\operatorname{sgn}(z)h_m(z)\,\,\mathrm d\mu_beta(z)
=E_m(beta).
\end{equation}
Define the raw alternatives $G_{m,+},G_{m,-}$ by
\begin{equation}
\label{eq:raw-dual-pair}
\,\mathrm d G_{m,+}:=(1+h_m)\,\mathrm d\mu_beta,
\qquad
\,\mathrm d G_{m,-}:=(1-h_m)\,\mathrm d\mu_beta.
\end{equation}
They are probability measures on $[-1,1]$ such that:
\begin{enumerate}[label=(\alph*)]
\item their moments agree through degree $m$;
\item $G_{m,\pm}([-t,t])\le2t^beta$ for every $0<t\le1$;
\item $G_{m,-}=G_{m,+}^\dagger$ and
$
theta(G_{m,+})
=-theta(G_{m,-})
=E_m(beta).
$
\end{enumerate}
Moreover, for every $L\ge1$, let
\begin{equation}
\label{eq:adjusted-dual-pair}
\rho_L:=\min\{1,L/2\},
\qquad
H_0:=\frac12(\delta_{-1}+\delta_{+1}),
\qquad
H_{m,\pm}:=\rho_LG_{m,\pm}+(1-\rho_L)H_0.
\end{equation}
Then $H_{m,\pm}\in\mathcal G_{beta,L}$, their moments agree through degree $m$, $H_{m,-}=H_{m,+}^\dagger$, and
\begin{equation}
\label{eq:adjusted-dual-target}
theta(H_{m,+})
=-theta(H_{m,-})
=\rho_LE_m(beta).
\end{equation}

\label{lem:adjoint-tail}
Let $g\in L_1[0,1]$ and define
\[
u_k:=\int_0^1b_{k,n}(p)g(p)\,\,\mathrm d p,
\qquad k=0,\dots,n.
\]
Then
